  return String(s == null ? '' : s).replace(/[&<>"]/g, function (c) {
    return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c];
  });
}

function paintScope() {
  var bs = document.querySelectorAll('#scope .sg');
  for (var i = 0; i < bs.length; i++) {
    bs[i].className = 'sg' + (bs[i].getAttribute('data-scope') === scope ? ' on' : '');
  }
  $('sep').className = 'rowsw' + (scope === 'offline' ? '' : ' hide');
}

// 空名字就整行不显示 —— 之前会孤零零留一个「· 线上」在那里
function paintWho() {
  var txt = charName ? ('当前：' + charName) : '';
  $('who').textContent = txt;
  $('who').className = txt ? '' : 'hide';
}

function show(text) {
  $('msg').textContent = text;
  $('msg').className = text ? '' : 'hide';
  $('list').innerHTML = '';
  $('foot').textContent = '';
}

function load() {
  paintScope();
  return nuo.context().then(function (c) {
    charId = c && c.charId ? String(c.charId) : null;
    charName = (c && c.charName) || '';
    paintWho();
    if (!charId) { state = null; show('先打开一个聊天，再来开关世界书'); return; }
    return nuo.worldbook.config({ charId: charId, scope: scope }).then(function (s) {
      state = s;
      render();
    });
  }).catch(function (e) { show('读取失败：' + (e && e.message || e)); });
}

// 写回：整份 enabledBooks / disabledEntries 一起送
function persist(patch) {
  if (!state || !charId || busy) return Promise.resolve();
  busy = true;
  var body = {
    charId: charId, scope: scope,
    custom: patch.custom === undefined ? state.custom : patch.custom,
    enabledBooks: patch.enabledBooks || state.enabledBooks,
    disabledEntries: patch.disabledEntries || state.disabledEntries
  };
  if (patch.separate !== undefined) body.separate = patch.separate;
  return nuo.worldbook.set(body).then(function () {
    busy = false;
    // 切换「与线上分开」会换掉整份数据源，必须重读而不是就地改
    if (patch.separate !== undefined) return load();
    state.custom = body.custom;
    state.enabledBooks = body.enabledBooks;
    state.disabledEntries = body.disabledEntries;
    render();
  }).catch(function (e) { busy = false; show('保存失败：' + (e && e.message || e)); });
}

function has(arr, v) { return arr.indexOf(String(v)) >= 0; }
function without(arr, v) { return arr.filter(function (x) { return String(x) !== String(v); }); }
function withv(arr, v) { return has(arr, v) ? arr.slice() : arr.concat([String(v)]); }

function render() {
  if (!state) return;
  $('msg').className = 'hide';
  $('custChk').checked = !!state.custom;
  $('sepChk').checked = !!state.separate;
  $('custHint').textContent = state.custom
    ? '勾选的书才生效，词条可单独关'
    : '跟着名册／全局走，要改先打开';
  $('list').className = state.custom ? '' : 'off';

  var q = $('q').value.trim().toLowerCase();
  var html = '';
  var shown = 0, onBooks = 0, onEnts = 0;

  for (var i = 0; i < state.books.length; i++) {
    var b = state.books[i];
    var ents = b.entries || [];
    var on = has(state.enabledBooks, b.id);
    var live = ents.filter(function (e) { return !e.uid || !has(state.disabledEntries, e.uid); });
    if (on) { onBooks++; onEnts += live.length; }

    var hitBook = !q || (b.name || '').toLowerCase().indexOf(q) >= 0;
    var hitEnts = ents.filter(function (e) {
      return !q || hitBook || (e.name || '').toLowerCase().indexOf(q) >= 0
        || (e.keys || '').toLowerCase().indexOf(q) >= 0;
    });
    if (!hitBook && !hitEnts.length) continue;
    shown++;

    var expanded = !!open[b.id] || (!!q && !hitBook);
    html += '<div class="bk"><div class="bkr">'
      + '<button class="arw' + (ents.length ? (expanded ? ' op' : '') : ' no')
      + '" data-arw="' + esc(b.id) + '">&#9654;</button>'
      + '<div class="bkn"><div class="bkt"><em>' + esc(b.name || '未命名') + '</em>'
      + (b.isGlobal ? '<span class="tag g">全局</span>' : '')
      + (b.fromRoster ? '<span class="tag">名册</span>' : '')
      + '</div><div class="bks">'
      + (ents.length ? (on ? (live.length + ' / ' + ents.length + ' 条生效') : (ents.length + ' 条词条')) : '空书')
      + '</div></div>'
      + '<label class="sw"><input type="checkbox" data-book="' + esc(b.id) + '"'
      + (on ? ' checked' : '') + (state.custom ? '' : ' disabled') + '><i></i></label>'
      + '</div>';

    if (expanded && ents.length) {
      var list = (q && !hitBook) ? hitEnts : ents;
      html += '<div class="ents"><div class="all">'
        + '<button data-all="on" data-bid="' + esc(b.id) + '">全开</button>'
        + '<button data-all="off" data-bid="' + esc(b.id) + '">全关</button></div>';
      for (var j = 0; j < list.length; j++) {
        var e = list[j];
        var eon = e.uid ? !has(state.disabledEntries, e.uid) : true;
        html += '<div class="ent"><span class="entn"><b>' + esc(e.name || ('#' + (j + 1)))
          + (e.constant ? ' <span class="tag">常驻</span>' : '') + '</b>'
          + (e.keys ? '<i>' + esc(e.keys) + '</i>' : '') + '</span>'
          + '<label class="sw sm"><input type="checkbox" data-ent="' + esc(e.uid) + '"'
          + ((eon && on) ? ' checked' : '')
          + ((!e.uid || !on || !state.custom) ? ' disabled' : '') + '><i></i></label></div>';
      }
      html += '</div>';
    }
    html += '</div>';
  }

  $('list').innerHTML = shown ? html
    : '<div style="font-size:11.5px;opacity:.6;text-align:center;padding:24px 12px">'
      + (q ? '没有匹配的世界书' : '还没有世界书') + '</div>';
  $('foot').textContent = state.books.length
    ? ('本聊天生效：' + onBooks + ' 本书 · ' + onEnts + ' 条词条')
    : '';
}

// 事件委托：列表整块重绘，逐个绑定会随重绘一起失效
$('list').addEventListener('click', function (ev) {
  var t = ev.target;
  var arw = t.getAttribute && t.getAttribute('data-arw');
  if (arw) { open[arw] = !open[arw]; render(); return; }
  var all = t.getAttribute && t.getAttribute('data-all');
  if (all && state && state.custom) {
    var bid = t.getAttribute('data-bid');
    var bk = state.books.filter(function (b) { return b.id === bid; })[0];
    if (!bk) return;
    var dis = state.disabledEntries.slice();
    (bk.entries || []).forEach(function (e) {
      if (!e.uid) return;
      dis = all === 'on' ? without(dis, e.uid) : withv(dis, e.uid);
    });
    persist({ disabledEntries: dis });
  }
});

$('list').addEventListener('change', function (ev) {
  var t = ev.target;
  if (!state || !state.custom) return;
  var bid = t.getAttribute('data-book');
  if (bid) {
    persist({ enabledBooks: t.checked ? withv(state.enabledBooks, bid) : without(state.enabledBooks, bid) });
    return;
  }
  var uid = t.getAttribute('data-ent');
  if (uid) {
    // 禁用集：关掉才进集合，打开就是从集合里拿掉
    persist({ disabledEntries: t.checked ? without(state.disabledEntries, uid) : withv(state.disabledEntries, uid) });
  }
});

$('custChk').addEventListener('change', function () {
  if (!state) return;
  // 从关到开：以当前继承集合为起点，否则一开就变成「一本书都没勾」
  var next = (this.checked && (!state.enabledBooks || !state.enabledBooks.length))
    ? (state.inherited || []) : state.enabledBooks;
  persist({ custom: this.checked, enabledBooks: next });
});

$('sepChk').addEventListener('change', function () { persist({ separate: this.checked }); });
$('q').addEventListener('input', function () { render(); });
$('refresh').addEventListener('click', function () { load(); });

var sgs = document.querySelectorAll('#scope .sg');
for (var k = 0; k < sgs.length; k++) {
  sgs[k].addEventListener('click', function () {
    scope = this.getAttribute('data-scope');
    try { nuo.storage.set('scope', scope); } catch (e) {}
    load();
  });
}

// 换聊天了就重读 —— 悬浮窗是常驻的，不重读会对着上一个角色开关
nuo.on('chatOpen', function () { load(); });

nuo.storage.get('scope').then(function (v) {
  if (v === 'online' || v === 'offline') scope = v;
}).catch(function () {}).then(function () {
  nuo.ready();
  load();
});
